pub fn overlay(registry: &RegistryDb, root: &Path, s: &mut WorkspaceSettings) {
    let a = access(registry, root);
    s.permissions.mode = a.mode;
    s.yolo.default = a.yolo;
    s.limits = a.limits.unwrap_or_default();
    s.sandbox_mode = a.sandbox_mode;
    s.tool_enforcement = a.tool_enforcement;
    s.sandbox_network = a.sandbox_network;
    s.sandbox_allowed_hosts = a.sandbox_allowed_hosts;
    s.sandbox_decoys = a.sandbox_decoys;
    s.sandbox_readable = a.sandbox_readable;
    s.sandbox_loopback = a.sandbox_loopback;
    s.sandbox_blocked_ports = a.sandbox_blocked_ports;
}

pub fn save_settings(&self, settings: &WorkspaceSettings) -> Result<(), Vec<ValidationIssue>> {
    let issues = self.validate(settings);
    if !issues.is_empty() {
        return Err(issues);
    }
    self.write_settings(settings).map_err(|e| {
        vec![ValidationIssue {
            path: String::new(),
            message: e.to_string(),
        }]
    })?;
    self.sync_projects();
    Ok(())
}

/// Blocked loopback ports a workspace may list, because each is a rule in every sandbox policy.
pub const MAX_BLOCKED_PORTS: usize = 64;

/// A `sandbox_blocked_ports` list: real ports, at most [`MAX_BLOCKED_PORTS`].
fn validate_blocked_ports(ports: &[u16]) -> Vec<ValidationIssue> {
    let mut issues: Vec<ValidationIssue> = ports
        .iter()
        .enumerate()
        .filter(|(_, p)| **p == 0)
        .map(|(i, _)| ValidationIssue {
            path: format!("sandbox_blocked_ports[{i}]"),
            message: "Write a port from 1 to 65535, because port 0 names no service.".into(),
        })
        .collect();
    if ports.len() > MAX_BLOCKED_PORTS {
        issues.push(ValidationIssue {
            path: "sandbox_blocked_ports".into(),
            message: format!(
                "List at most {MAX_BLOCKED_PORTS} ports, because each one is a rule in every sandbox policy."
            ),
        });
    }
    issues
}

#[test]
fn setting_keys_name_fields() {
    let json = serde_json::to_value(WorkspaceSettings::seeded("x")).unwrap();
    for (key, _) in SETTING_KEYS {
        let found = key.split('.').try_fold(&json, |v, part| v.get(part));
        assert!(found.is_some(), "{key} is not a settings field");
    }
}
